<?php
declare(strict_types=1);require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/auth.php';require_admin();$q=$pdo->query('SELECT s.id_servicio,s.numero_servicio,c.nombre,c.email,c.telefono,s.tipo_dispositivo,s.marca,s.descripcion_dano,s.estado,s.fecha_recepcion FROM servicios s INNER JOIN clientes c ON c.id_cliente=s.id_cliente WHERE s.creado_por IS NULL AND s.eliminado_en IS NULL ORDER BY s.fecha_recepcion DESC');$items=$q->fetchAll();
?>
